/* Ghost Cat — framework-independent, self-contained 2D animation. */
(()=>{if(customElements.get('ghost-cat-animation'))return;
const TEMPLATE="<style>:host{display:block;width:100%;contain:content}svg{display:block;width:100%;height:auto;overflow:hidden}</style><svg xmlns=\"http://www.w3.org/2000/svg\" id=\"scene\" viewBox=\"0 0 960 1230\" role=\"img\" aria-label=\"\ud770 \ub9dd\ud1a0\ub97c \uc4f4 \ud30c\ub780 \uace0\uc591\uc774\uac00 \uc67c\ucabd\uc5d0\uc11c \uac78\uc5b4\uc640 \uc549\ub294 \uc560\ub2c8\uba54\uc774\uc158\">\n<defs>\n <radialGradient id=\"ground\"><stop stop-color=\"#b6c9e4\" stop-opacity=\".19\"/><stop offset=\"1\" stop-color=\"#b6c9e4\" stop-opacity=\"0\"/></radialGradient>\n <linearGradient id=\"fur\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop stop-color=\"#e8f3fc\"/><stop offset=\"1\" stop-color=\"#dcebf9\"/></linearGradient>\n <clipPath id=\"bodyCut\"><path d=\"M399 380 C411 284 427 231 449 230 C471 229 510 274 535 300 C581 295 624 306 658 323 C709 291 756 264 773 279 C789 309 783 381 768 434 C802 512 808 632 829 697 C848 752 874 792 893 849 C905 888 902 932 922 952 C949 964 955 985 935 996 C909 1017 851 1015 816 1000 C772 979 753 1014 714 1012 C685 1014 667 994 653 974 C675 1001 690 1005 695 1006 C663 1020 592 1024 572 1012 C562 1029 508 1030 491 1018 C458 1025 423 1023 423 1003 C417 998 415 992 422 987 C378 995 348 980 343 955 C330 946 295 950 277 943 C252 938 253 921 261 906 C284 860 310 779 321 709 C337 628 328 541 355 465 C373 421 381 409 399 380 Z\"/></clipPath>\n <clipPath id=\"tailCut\"><path d=\"M894 915 C920 897 937 872 935 836 C934 795 903 758 886 717 C871 679 879 641 897 620 C923 588 962 582 986 602 C1008 618 1005 644 980 650 C948 650 940 671 944 696 C948 723 974 761 984 790 C1007 852 986 920 934 956 L916 965 L892 928Z\"/></clipPath>\n <mask id=\"legMask\" maskUnits=\"userSpaceOnUse\" x=\"200\" y=\"200\" width=\"850\" height=\"860\"><rect x=\"200\" y=\"200\" width=\"850\" height=\"860\" fill=\"white\"/><path d=\"M427 830 L582 829 L605 947 L577 1029 L420 1029 L422 967 Z\" fill=\"black\"/></mask>\n <image id=\"original\" width=\"1254\" height=\"1254\" href=\"data:image/png;base64,\"/>\n</defs>\n<ellipse id=\"shadow\" cx=\"470\" cy=\"441\" rx=\"142\" ry=\"19\" fill=\"url(#ground)\"/>\n<g id=\"traveller\">\n <svg width=\"310\" height=\"326\" viewBox=\"230 210 800 840\" overflow=\"visible\">\n  <g id=\"tail\"><use href=\"#original\" clip-path=\"url(#tailCut)\"/></g>\n  <g id=\"walkRig\">\n   <g id=\"bodyBob\">\n    <path d=\"M426 811 Q489 791 576 821 L583 965 Q549 989 461 977 L439 941Z\" fill=\"url(#fur)\"/>\n    <use href=\"#original\" clip-path=\"url(#bodyCut)\" mask=\"url(#legMask)\"/>\n   </g>\n   <g id=\"farLeg\"><path d=\"M534 837 C538 874 532 930 527 965 C517 980 509 983 506 996 C502 1012 514 1021 537 1020 C563 1021 571 1006 580 983 C588 956 590 929 589 902\" fill=\"url(#fur)\" stroke=\"#a1bce3\" stroke-width=\"3.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g>\n   <g id=\"nearLeg\"><path d=\"M456 830 C463 876 469 937 463 972 C449 980 441 987 441 1000 C442 1016 457 1022 481 1019 C504 1019 514 1009 518 990 C523 946 526 891 523 843\" fill=\"url(#fur)\" stroke=\"#a1bce3\" stroke-width=\"3.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M479 1019 Q475 1007 484 1001\" fill=\"none\" stroke=\"#a1bce3\" stroke-width=\"3.6\" stroke-linecap=\"round\"/></g>\n  </g>\n  <g id=\"seated\" opacity=\"0\"><use href=\"#original\" clip-path=\"url(#bodyCut)\"/></g>\n </svg>\n</g>\n</svg>";
class GhostCatAnimation extends HTMLElement {
 constructor(){super();this.attachShadow({mode:'open'});this._time=0;this._playing=false;this._last=null;this._done=false;}
 get duration(){return 9.2;}
 get currentTime(){return this._time;}
 set currentTime(v){this._time=Math.max(0,Math.min(this.duration,Number(v)||0));this._done=this._time>=5.25;if(this._els)this._draw();}
 get speed(){const v=Number(this.getAttribute('speed')||1);return Number.isFinite(v)?Math.max(.25,Math.min(3,v)):1;}
 get loop(){return this.hasAttribute('loop');}
 set loop(v){this.toggleAttribute('loop',Boolean(v));}
 connectedCallback(){this.shadowRoot.innerHTML=TEMPLATE;this._els={};for(const id of ['traveller','bodyBob','nearLeg','farLeg','tail','walkRig','seated','shadow'])this._els[id]=this.shadowRoot.getElementById(id);this.setAttribute('role','img');this.setAttribute('aria-label','흰 망토를 입은 파란 고양이가 걸어와 앉는 애니메이션');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;this._time=reduced?5.3:0;this._playing=!reduced&&!this.hasAttribute('paused');this._done=reduced;this._last=null;this._draw();this._tick=t=>{if(!this.isConnected)return;if(this._last===null)this._last=t;const dt=Math.min((t-this._last)/1000,.05);this._last=t;if(this._playing&&!document.hidden){this._time+=dt*this.speed;if(this._time>=5.25&&!this._done){this._done=true;this.dispatchEvent(new CustomEvent('sitcomplete',{bubbles:true,composed:true}));}if(this._time>=this.duration){if(this.loop){this._time=0;this._done=false;}else{this._time=this.duration;this._playing=false;}}this._draw();}this._raf=requestAnimationFrame(this._tick);};this._raf=requestAnimationFrame(this._tick);}
 disconnectedCallback(){cancelAnimationFrame(this._raf);this._last=null;}
 play(){if(this._time>=this.duration)this.replay();else this._playing=true;}
 pause(){this._playing=false;}
 replay(){this._time=0;this._done=false;this._playing=true;this._last=null;if(this._els)this._draw();}
 finish(){this.currentTime=5.3;this._playing=false;}
 _draw(){const t=this._time,E=this._els,clamp=x=>Math.max(0,Math.min(1,x)),smooth=x=>{x=clamp(x);return x*x*(3-2*x);};
 const arriving=t<3.8,settling=t>=3.8&&t<5.25,done=t>=5.25,u=clamp((t-3.1)/.7),stop=smooth(u),amp=1-stop;
 const travelled=t<=3.1?t:3.1+.7*(u-u*u*u+.5*u*u*u*u),x=-295+620*travelled/3.45;
 const step=t*Math.PI*4,s=smooth((t-3.8)/1.1),bounce=settling?Math.sin(clamp((t-3.8)/1.45)*Math.PI*2)*Math.exp(-clamp((t-3.8)/1.45)*3):0,height=arriving?Math.abs(Math.sin(step))*3.7*amp:0,breath=done?Math.sin((t-5.25)*1.7)*.003:0;
 E.traveller.setAttribute('transform',`translate(${arriving?x:325},${131+bounce*3-height}) translate(155,310) scale(${.98+.02*s-breath*.2},${1.09-.09*s+breath}) translate(-155,-310)`);
 E.bodyBob.setAttribute('transform',`rotate(${Math.sin(step)*.65*amp},620,930)`);
 E.nearLeg.setAttribute('transform',`rotate(${Math.sin(step)*8*amp},485,835) translate(${Math.sin(step)*7*amp},${-Math.max(0,Math.cos(step))*21*amp})`);
 E.farLeg.setAttribute('transform',`rotate(${-Math.sin(step)*8*amp},555,841) translate(${-Math.sin(step)*7*amp},${-Math.max(0,-Math.cos(step))*21*amp})`);
 E.tail.setAttribute('transform',`rotate(${arriving?Math.sin(step*.5)*3.7*amp:Math.sin((t-3.8)*2)*2.2},906,925)`);
 const reveal=smooth((t-4.1)/.7);E.walkRig.setAttribute('opacity',1-reveal);E.seated.setAttribute('opacity',reveal);E.shadow.setAttribute('cx',(arriving?x:325)+153);E.shadow.setAttribute('rx',105+22*s-height);E.shadow.setAttribute('opacity',.82+.18*s);
 }
}
customElements.define('ghost-cat-animation',GhostCatAnimation);
})();
